const grid=document.querySelector('#game-grid'),search=document.querySelector('#search-input'),chips=[...document.querySelectorAll('.chip')],toast=document.querySelector('#toast');
let activeFilter='Semua',visible=6,items=[];
const favorites=new Set(JSON.parse(localStorage.getItem('nm-favorites')||'[]'));
function getItems(){return items.filter(x=>x.active!==false)}
function escapeHTML(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function filtered(){const q=search.value.trim().toLowerCase();return getItems().filter(x=>(activeFilter==='Semua'||x.category===activeFilter)&&(`${x.title} ${x.category} ${x.platform}`).toLowerCase().includes(q))}
function imageMarkup(x){return x.image?`<img src="${escapeHTML(x.image)}" alt="Gambar ${escapeHTML(x.title)}" loading="lazy">`:''}
function rankingImage(x){return x?.image?`<img src="${escapeHTML(x.image)}" alt="Gambar ${escapeHTML(x.title)}">`:''}
function ratingLabel(x){return Number(x?.rankRating||x?.rating||0).toFixed(1)}
function renderHeroRanking(ranked){
  const host=document.querySelector('#hero-ranking'),top=ranked.slice(0,3);if(!host||!top.length)return;
  const main=top[0],second=top[1]||main,third=top[2]||second;
  const mainCard=`<a class="hero-card main-card" href="${NMData.detailUrl(main.id)}" aria-label="Peringkat 1: ${escapeHTML(main.title)}"><div class="poster ${NMData.coverClass(main.category)}">${rankingImage(main)}<span class="rank-number">#1 TERPOPULER</span><span class="hero-category">${escapeHTML(main.category)}</span><b>${escapeHTML(main.title)}</b></div><div class="card-meta"><span class="platform-tag">${escapeHTML(main.platform)}</span><span>★ ${ratingLabel(main)} · ${Number(main.clicks||0)} klik</span></div></a>`;
  const mini=(x,position,rank)=>`<a class="hero-card mini-card ${position} ${NMData.coverClass(x.category)}" href="${NMData.detailUrl(x.id)}" aria-label="Peringkat ${rank}: ${escapeHTML(x.title)}">${rankingImage(x)}<span class="rank-number">#${rank}</span><span class="hero-category">${escapeHTML(x.category)}</span><b>${escapeHTML(x.title)}</b><small>★ ${ratingLabel(x)} · ${Number(x.clicks||0)} klik</small></a>`;
  host.querySelector('.hero-ranking-loading')?.remove();host.insertAdjacentHTML('beforeend',mainCard+mini(second,'one',2)+mini(third,'two',3));
}
function card(x){const rating=x.ratingCount?`${Number(x.communityRating).toFixed(1)} (${x.ratingCount})`:x.rating||'Baru';return `<article class="game-card reveal visible" data-open="${x.id}" tabindex="0" role="link" aria-label="Buka detail ${escapeHTML(x.title)}"><div class="game-cover ${NMData.coverClass(x.category)}">${imageMarkup(x)}<span class="cover-badge">${escapeHTML(x.platform)}</span><button class="favorite ${favorites.has(x.id)?'active':''}" data-favorite="${x.id}" aria-label="Simpan favorit">${favorites.has(x.id)?'♥':'♡'}</button><span class="cover-type">${escapeHTML(x.category)} · NUSANTARA MOD</span></div><div class="game-info"><div class="game-title-row"><h3>${escapeHTML(x.title)}</h3><span class="rating">★ ${escapeHTML(rating)}</span></div><p>${escapeHTML(x.description)}</p><div class="game-details"><span>${escapeHTML(x.version)}</span><span>${escapeHTML(x.size)}</span><span>${escapeHTML(x.platform)}</span></div><a class="card-button" href="${NMData.detailUrl(x.id)}">Lihat detail mod →</a></div></article>`}
function render(){const shown=filtered();grid.innerHTML=shown.slice(0,visible).map(card).join('');document.querySelector('#empty-state').hidden=shown.length>0;document.querySelector('#load-more').hidden=visible>=shown.length;document.querySelector('#stat-mods').textContent=`${getItems().length}+`}
function notify(text){toast.textContent=text;toast.classList.add('show');clearTimeout(notify.t);notify.t=setTimeout(()=>toast.classList.remove('show'),2800)}
function openItem(id){location.href=NMData.detailUrl(id)}
grid.addEventListener('click',e=>{const fav=e.target.closest('[data-favorite]');if(fav){e.preventDefault();e.stopPropagation();const id=fav.dataset.favorite;favorites.has(id)?favorites.delete(id):favorites.add(id);localStorage.setItem('nm-favorites',JSON.stringify([...favorites]));render();notify(favorites.has(id)?'Ditambahkan ke favorit':'Dihapus dari favorit');return}const cardEl=e.target.closest('[data-open]');if(cardEl&&!e.target.closest('a'))openItem(cardEl.dataset.open)});
grid.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('button,a')){e.preventDefault();openItem(e.target.closest('[data-open]')?.dataset.open)}});
search.addEventListener('input',()=>{visible=6;render()});chips.forEach(c=>c.addEventListener('click',()=>{chips.forEach(x=>x.classList.remove('active'));c.classList.add('active');activeFilter=c.dataset.filter;visible=6;render()}));
document.querySelector('#load-more').addEventListener('click',()=>{visible+=6;render()});
document.querySelector('.nav-toggle').addEventListener('click',e=>{const menu=document.querySelector('#nav-links');menu.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',menu.classList.contains('open'))});
document.querySelectorAll('[data-toast]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();notify(a.dataset.toast)}));
document.querySelector('#year').textContent=new Date().getFullYear();
const observer=new IntersectionObserver(entries=>entries.forEach(x=>{if(x.isIntersecting)x.target.classList.add('visible')}),{threshold:.12});document.querySelectorAll('.reveal').forEach(x=>observer.observe(x));
(async()=>{grid.innerHTML='<div class="empty-state"><h3>Memuat koleksi…</h3><p>Mengambil data terbaru dari server.</p></div>';try{items=await NMData.get();render();const fallback=[...getItems()].sort((a,b)=>Number(b.rating||0)-Number(a.rating||0)||Number(b.clicks||0)-Number(a.clicks||0)),ranked=await NMData.getRanking(items).catch(()=>fallback),ratingMap=new Map(ranked.map(item=>[item.id,item]));items=items.map(item=>{const rated=ratingMap.get(item.id);return rated?{...item,communityRating:rated.communityRating||0,ratingCount:rated.ratingCount||0}:item});render();renderHeroRanking(ranked)}catch(error){grid.innerHTML='<div class="empty-state"><h3>Koleksi belum dapat dimuat</h3><p>Periksa koneksi internet lalu muat ulang halaman.</p></div>';notify(error.message)}})();
